import React, { useState, useEffect, useRef } from 'react';

const VoiceWeb = ({ onNavigate }) => {
    const [isListening, setIsListening] = useState(false);
    const [messages, setMessages] = useState([]);
    const [currentStep, setCurrentStep] = useState('idle'); 
    const [selectedLanguage, setSelectedLanguage] = useState({ name: 'Telugu', code: 'te-IN' }); // Default to prevent null errors
    const [activeService, setActiveService] = useState(null);
    const scrollRef = useRef(null);
    const recognitionRef = useRef(null);

    const languages = [
        { name: 'English', code: 'en-IN', native: 'English' },
        { name: 'Telugu', code: 'te-IN', native: 'తెలుగు (Telugu)' },
        { name: 'Hindi', code: 'hi-IN', native: 'हिन्दी (Hindi)' },
        { name: 'Tamil', code: 'ta-IN', native: 'தமிழ் (Tamil)' },
        { name: 'Kannada', code: 'kn-IN', native: 'కన్నడ (Kannada)' },
        { name: 'Malayalam', code: 'ml-IN', native: 'మలయాళం (Malayalam)' },
        { name: 'Bengali', code: 'bn-IN', native: 'বাংলা (Bengali)' },
        { name: 'Marathi', code: 'mr-IN', native: 'మరాఠీ (Marathi)' },
        { name: 'Gujarati', code: 'gu-IN', native: 'గుజరాతీ (Gujarati)' },
        { name: 'Punjabi', code: 'pa-IN', native: 'పంజాబీ (Punjabi)' }
    ];

    const flows = {
        'Flight Booking': {
            'en-IN': ["From which city?", "To which city?", "What date?", "Which class?"],
            'te-IN': ["ఏ నగరం నుండి?", "ఏ నగరానికి?", "ఏ తేదీన?", "ఏ తరగతి?"],
            'hi-IN': ["कहाँ से?", "कहाँ तक?", "किस तारीख को?", "कौन सी क्लास?"]
        },
        'Live Status': {
            'en-IN': ["Please say your flight number.", "Is it for today or tomorrow?"],
            'te-IN': ["దయచేసి మీ ఫ్లైట్ నంబర్ చెప్పండి.", "ఇది ఈరోజుకా లేక రేపటికా?"],
            'hi-IN': ["कृपया अपना फ्लाइट नंबर बताएं।", "क्या यह आज के लिए है या कल के लिए?"]
        }
    };

    const speak = (text, langCode) => {
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = langCode || 'en-IN';
        utterance.onend = () => { if (currentStep !== 'completed') startListening(langCode); };
        window.speechSynthesis.speak(utterance);
    };

    const startListening = (langCode) => {
        const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
        if (!SpeechRecognition) return;
        const recognition = new SpeechRecognition();
        recognitionRef.current = recognition;
        recognition.lang = langCode || 'en-IN';
        recognition.onstart = () => setIsListening(true);
        recognition.onend = () => setIsListening(false);

        recognition.onresult = (event) => {
            const transcript = event.results[0][0].transcript;
            addMessage("user", transcript); 

            if (currentStep === 'choosing_lang') {
                const found = languages.find(l => transcript.toLowerCase().includes(l.name.toLowerCase()) || transcript.includes('తెలుగు'));
                const lang = found || { name: 'Telugu', code: 'te-IN' };
                setSelectedLanguage(lang);
                setCurrentStep('choosing_service');
                const q = lang.code === 'te-IN' ? "మీకు ఏ సేవ కావాలి?" : "Which service do you need?";
                addMessage("ai", q);
                speak(q, lang.code);
            } 
            else if (currentStep === 'choosing_service') {
                const service = transcript.toLowerCase().includes('status') ? 'Live Status' : 'Flight Booking';
                setActiveService(service);
                setCurrentStep(0);
                const firstQ = flows[service][selectedLanguage.code][0];
                addMessage("ai", firstQ);
                speak(firstQ, selectedLanguage.code);
            } 
            else {
                const nextStep = currentStep + 1;
                const serviceFlow = flows[activeService || 'Flight Booking'][selectedLanguage.code];
                if (nextStep < serviceFlow.length) {
                    setCurrentStep(nextStep);
                    const nextQ = serviceFlow[nextStep];
                    addMessage("ai", nextQ);
                    speak(nextQ, selectedLanguage.code);
                } else {
                    setCurrentStep('completed');
                    const end = selectedLanguage.code === 'te-IN' ? "ధన్యవాదాలు! పూర్తి అయింది." : "Thank you! Done.";
                    addMessage("ai", end);
                    speak(end, selectedLanguage.code);
                }
            }
        };
        recognition.start();
    };

    const addMessage = (sender, text) => { setMessages(prev => [...prev, { sender, text }]); };

    const startConversation = () => {
        setCurrentStep('choosing_lang');
        const msg = "Welcome to SkySync. Please say your language.";
        addMessage("ai", msg);
        speak(msg, "en-IN");
    };

    useEffect(() => { if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight; }, [messages]);

    return (
        <div style={{ background: '#0a0f1e', height: '100vh', display: 'flex', flexDirection: 'column', color: 'white' }}>
            {/* Top Header */}
            <div style={{ height: '70px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0 30px', borderBottom: '1px solid #1e293b' }}>
                <div style={{ display: 'flex', alignItems: 'center' }}>
                    <div onClick={() => onNavigate('dashboard')} style={{ cursor: 'pointer', color: '#60a5fa', fontSize: '24px', marginRight: '20px' }}>←</div>
                    <span style={{ fontWeight: 'bold', letterSpacing: '2px' }}>SKY-SYNC AI</span>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
                    <div style={{ fontSize: '20px' }}>🔔</div>
                    <div style={{ width: '40px', height: '40px', borderRadius: '50%', background: '#3b82f6', border: '2px solid #60a5fa' }}></div>
                </div>
            </div>

            <div style={{ flex: 1, display: 'flex', padding: '20px', gap: '20px', overflow: 'hidden' }}>
                {/* Languages Sidebar */}
                <div style={{ width: '300px', background: 'rgba(255,255,255,0.02)', borderRadius: '24px', padding: '15px', border: '1px solid #1e293b' }}>
                    <h4 style={{ fontSize: '12px', color: '#64748b', marginBottom: '15px' }}>LANGUAGES</h4>
                    {languages.map((l, i) => (
                        <div key={i} style={{ padding: '10px 15px', borderRadius: '12px', fontSize: '13px', border: '1px solid #1e293b', marginBottom: '8px', 
                        background: selectedLanguage?.code === l.code ? 'rgba(59, 130, 246, 0.2)' : 'transparent' }}>{l.native}</div>
                    ))}
                </div>

                {/* Main Chat Area */}
                <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '20px' }}>
                    <div ref={scrollRef} style={{ flex: 1, background: 'rgba(0,0,0,0.3)', borderRadius: '24px', padding: '20px', overflowY: 'auto' }}>
                        {messages.map((m, i) => (
                            <div key={i} style={{ display: 'flex', justifyContent: m.sender === 'ai' ? 'flex-start' : 'flex-end', marginBottom: '15px' }}>
                                <div style={{ background: m.sender === 'ai' ? '#1e293b' : '#3b82f6', padding: '12px 18px', borderRadius: '15px', maxWidth: '70%' }}>{m.text}</div>
                            </div>
                        ))}
                    </div>
                    <div style={{ height: '140px', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', background: 'rgba(255,255,255,0.02)', borderRadius: '24px' }}>
                        <div onClick={startConversation} style={{ width: '60px', height: '60px', borderRadius: '50%', background: isListening ? '#ef4444' : '#3b82f6', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}>🎤</div>
                        <span style={{ marginTop: '10px', fontSize: '11px', color: '#64748b' }}>{isListening ? "LISTENING..." : "CLICK TO START"}</span>
                    </div>
                </div>

                {/* Right Panel - ALL 10 SERVICES RESTORED */}
                <div style={{ width: '320px', display: 'flex', flexDirection: 'column', gap: '15px' }}>
                    <div style={{ background: 'rgba(255,255,255,0.02)', borderRadius: '24px', padding: '15px', border: '1px solid #1e293b' }}>
                        <h4 style={{ fontSize: '11px', color: '#64748b', marginBottom: '10px' }}>SERVICES</h4>
                        {['Flight Booking', 'Live Status', 'Web Check-in', 'Baggage Claim', 'Meal Request', 'Seat Upgrade', 'Refund Status', 'Support', 'Cancel Trip', 'Group Booking'].map(s => (
                            <div key={s} style={{ padding: '8px 12px', background: 'rgba(255,255,255,0.03)', borderRadius: '10px', marginBottom: '5px', fontSize: '12px' }}>{s}</div>
                        ))}
                    </div>
                    <div style={{ flex: 1, background: 'rgba(59, 130, 246, 0.05)', borderRadius: '24px', padding: '15px', border: '1px solid rgba(59, 130, 246, 0.2)' }}>
                        <h4 style={{ fontSize: '10px', color: '#3b82f6', marginBottom: '10px' }}>LIVE FLIGHT RADAR</h4>
                        <div style={{ fontSize: '11px', fontFamily: 'monospace', color: '#60a5fa' }}>
                            ✈️ AI-204 | BOM-LHR | ON TIME<br/>
                            ✈️ EK-501 | DXB-HYD | DELAY 15m
                            <div style={{ marginTop: '15px', borderTop: '1px solid rgba(59, 130, 246, 0.2)', paddingTop: '10px' }}>
                                ENGINE: {selectedLanguage?.name || 'IDLE'}<br/>
                                STATUS: {currentStep === 'idle' ? 'STANDBY' : 'PROCESSING'}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default VoiceWeb;
